INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (1, 'Un giorno all''improvviso', 'Un giorno all''improvviso m''innamorai di te, il cuore mi batteva non chiedermi perché! Di tempo ne è passato ma sono ancora qua, ed oggi come allora difendo la città! Alè alè alè, alè alè alè...', '/audio/cori/un_giorno_all_improvviso.mp3', 2015, 'Curva B', 'Riadattamento del brano ''L''estate sta finendo'' dei Righeira (1985). Divenuto celeberrimo nella stagione 2015-16 sotto la guida di Maurizio Sarri, cantato dai calciatori abbracciati sotto le due curve dopo ogni vittoria.', 'alta', 1, 5);
INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (2, '''O surdato ''nnammurato', 'Oje vita, oje vita mia... oje core ''e chistu core... si'' stata ''o primmo ammore... e ''o primmo e ll''ùrtemo saraje pe'' me!', '/audio/cori/o_surdato_nnammurato.mp3', 1975, 'Curva A', 'Scritta nel 1915 dal poeta Aniello Califano e musicata da Enrico Cannio. Venne adottata come inno spontaneo della tifoseria azzurra nel 1975 dopo una storica vittoria per 1-0 a San Siro contro la capolista Juventus.', 'alta', 1, 5);
INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (3, 'Sarò con te', 'Sarò con te... e tu non devi mollare, abbiamo un sogno nel cuore: Napoli torna campione! E se ne va, la capolista se ne va!', '/audio/cori/saro_con_te.mp3', 2017, 'Curva B', 'Il coro manifesto dell''era contemporanea che ha scandito le stagioni del grande gioco e accompagnato la marcia trionfale verso il 3° Scudetto del 2023.', 'alta', 1, 5);
INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (4, 'Il Canto delle Curve (Tanto già lo so)', 'Tanto già lo so che l''anno prossimo gioco di sabato! Ma non fa niente, io sarò sempre con te, ovunque tu sarai io ti seguirò...', '/audio/cori/tanto_gia_lo_so.mp3', 1998, 'Curva B', 'Nato negli anni più bui della retrocessione e della Serie B a fine anni novanta, assurto a simbolo immortale di fedeltà assoluta e amore incondizionato per la maglia aldilà della categoria.', 'alta', 1, 5);
INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (5, 'La capolista se ne va', 'E se ne va, la capolista se ne va... la capolista se ne va!', '/audio/cori/capolista_se_ne_va.mp3', 1987, 'Curva B', 'Il coro leggendario degli anni ''80 intonato da tutto lo stadio San Paolo durante le fughe in vetta alla classifica degli scudetti del 1987 e del 1990.', 'alta', 1, 5);
INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (6, 'Napoli sei la vita mia', 'Napoli, Napoli... Napoli sei la vita mia! In ogni stadio ovunque andrai, da solo non ti lasceremo mai!', '/audio/cori/napoli_vita_mia.mp3', 1985, 'Curva A', 'Uno dei cori più longevi e cantati nelle trasferte di tutta Italia ed Europa fin dagli albori del tifo organizzato.', 'alta', 1, 5);
INSERT INTO cori (id, titolo, testo, audio_url, anno, curva, note_origini, confidence, verificato, fonte_id) VALUES (7, '10 Maggio 1987', 'Oh Mamma Mamma Mamma... sai perché mi batte il corazón? Ho visto Maradona, ho visto Maradona! Eh, mammà, innamorato son!', '/audio/cori/ho_visto_maradona.mp3', 1987, 'Curva B', 'L''inno universale dedicato a Diego Armando Maradona, cantato in tutto il pianeta e inciso nella memoria collettiva della città di Napoli.', 'alta', 1, 5);
